"""Measure expense checkpoints used by the three tutorial graphics."""
import hashlib,json
from pathlib import Path
from gnd.export.applications import execute_application
root=Path.cwd();example=root/'src/gnd/examples/expense';evidence=root/'.gnd-planning/milestones/pyrel-applications/evidence/PA4';target=evidence/'figure-source';target.mkdir(exist_ok=False)
rows=[]
scenarios=[('baseline','model.orm.json','seed.population.json','report','','',0),('team-lead','model.orm.json','seed.population.json','approve','101','team-lead',0),('finance','model.orm.json','seed.population.json','approve','102','finance',0),('meal-cap','model.orm.json','invalid-meal.population.json','report','','',1),('chain-limit','model.orm.json','invalid-chain.population.json','report','','',1),('currency-missing','currency.orm.json','currency-missing.population.json','report','','',1),('currency-explicit','currency.orm.json','currency.population.json','report','','',0)]
for name,model,population,command,expense,chain,expected in scenarios:
    output=target/(name+'.population.json')
    result=execute_application(example/model,example/population,output,native_python=root/'tutorials/runtimes/.venv/bin/python',query_script=example/'native_query.py',query_args=(command,expense,chain),owned_relations=('expense_is_approved','expense_approved_by_chain') if command=='approve' else (),allowed_guard_kinds=('unknown-expense','already-approved','unsupported-currency'))
    assert result['exit_code']==expected,result
    report=target/(name+'.report.json');report.write_text(json.dumps(result,sort_keys=True,indent=2)+'\n')
    rows.append({'scenario':name,'model':(example/model).relative_to(root).as_posix(),'model_sha256':hashlib.sha256((example/model).read_bytes()).hexdigest(),'input':(example/population).relative_to(root).as_posix(),'input_sha256':hashlib.sha256((example/population).read_bytes()).hexdigest(),'report':report.relative_to(root).as_posix(),'report_sha256':hashlib.sha256(report.read_bytes()).hexdigest(),'candidate':output.relative_to(root).as_posix() if output.exists() else None,'candidate_sha256':hashlib.sha256(output.read_bytes()).hexdigest() if output.exists() else None,'exit_code':expected})
receipt={'schema_version':1,'source':'Synthetic shipped expense facts/model limits and actual independent native calculation/checker outputs','unit':'EUR, whole-number amounts; no conversion','parent_sha256':hashlib.sha256((root/'src/gnd/export/applications.py').read_bytes()).hexdigest(),'query_sha256':hashlib.sha256((example/'native_query.py').read_bytes()).hexdigest(),'runtime_sha256':hashlib.sha256((root/'src/gnd/export/pyrel_runtime.py').read_bytes()).hexdigest(),'scenarios':rows,'graphics':{'reporting-flow':'baseline native calculation.report + accepted policy; team-lead/finance checked candidates','caps-chains':'source model policy_meals75/approval_limit_team_lead100/approval_limit_finance3000 EUR; meal-cap90 and chain-limit800 native witnesses','currency-evolution':'baseline implicit EUR2260; currency-missing required_expense_has_currency witnesses101/102; currency-explicit native EUR2260 accepted'},'limits':'Calculation evidence on rejected inputs is not a successful CLI report or actor/payment authorization.'}
(evidence/'figure-source.json').write_text(json.dumps(receipt,sort_keys=True,indent=2)+'\n')
print('seven native figure-source checkpoints measured')
